INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1197910, 151088, 6349, '<td valign="top">Beautiful composition and tones.  It gives the feeling that they are floating blissfully. 7</td>', 'Beautiful composition and tones.  It gives the feeling that they are floating blissfully. 7', '2005-02-28 02:09:20.000000', NULL, 1),
(1197913, 150933, 6349, '<td valign="top">Great black and white processing and use of natural window lighting.</td>', 'Great black and white processing and use of natural window lighting.', '2005-02-28 02:10:03.000000', NULL, 1),
(1197915, 151009, 6104, '<td valign="top">whoa.  That''s quite the illusion :D</td>', 'whoa.  That''s quite the illusion :D', '2005-02-28 02:10:48.000000', NULL, 1),
(1197917, 150552, 6349, '<td valign="top">Great idea.  Is she really juggling all those?!  If so that''s very impressive.  Hope you didn''t break too many clocks.  This would make excellent stock material.  7</td>', 'Great idea.  Is she really juggling all those?!  If so that''s very impressive.  Hope you didn''t break too many clocks.  This would make excellent stock material.  7', '2005-02-28 02:11:26.000000', NULL, 1),
(1197921, 151066, 6349, '<td valign="top">wow, do you really make your own toothpicks?  that''s insane!  also really cool.  You make me want to give it a try.</td>', 'wow, do you really make your own toothpicks?  that''s insane!  also really cool.  You make me want to give it a try.', '2005-02-28 02:12:19.000000', NULL, 1),
(1197924, 150908, 6349, '<td valign="top">I like this photo a lot.  Very interesting bus stop.  8</td>', 'I like this photo a lot.  Very interesting bus stop.  8', '2005-02-28 02:12:59.000000', NULL, 1),
(1197928, 151013, 6349, '<td valign="top">I think this is great.  Truly bizarre and original.  7</td>', 'I think this is great.  Truly bizarre and original.  7', '2005-02-28 02:14:47.000000', NULL, 1),
(1197930, 150729, 6349, '<td valign="top">I love this photo and I never would have guessed from the thumbnail.  The dullness and lack of colors really work.  Going in my favorites.  10</td>', 'I love this photo and I never would have guessed from the thumbnail.  The dullness and lack of colors really work.  Going in my favorites.  10', '2005-02-28 02:15:50.000000', NULL, 1),
(1197931, 151050, 6349, '<td valign="top">I actually thought of doing this for the challenge but couldn''t figure out how to show the actual motion of twiddling.  I see you also went for the motion.  It appears that the thumbs have nearly dissappeared entirely...i guess that''s what happens when you twiddle too long?   :)</td>', 'I actually thought of doing this for the challenge but couldn''t figure out how to show the actual motion of twiddling.  I see you also went for the motion.  It appears that the thumbs have nearly dissappeared entirely...i guess that''s what happens when you twiddle too long?   :)', '2005-02-28 02:17:06.000000', NULL, 1),
(1197932, 151050, 34039, '<td valign="top">II feel funny critiqueing anything as new to this as I am, but the site seems to encourage it.  I like the concept here, but it took me a minute to understand that you were capturing a motion blur.  If the thumbs were more visible and if there was less white in the photo, I think I would like it better.  Maybe a contrasting background.</td>', 'II feel funny critiqueing anything as new to this as I am, but the site seems to encourage it.  I like the concept here, but it took me a minute to understand that you were capturing a motion blur.  If the thumbs were more visible and if there was less white in the photo, I think I would like it better.  Maybe a contrasting background.', '2005-02-28 02:18:09.000000', NULL, 1),
(1197933, 150318, 6349, '<td valign="top">you have captured a true look of love with is a blessing. 7</td>', 'you have captured a true look of love with is a blessing. 7', '2005-02-28 02:18:26.000000', NULL, 1),
(1197937, 150552, 31213, '<td valign="top">GREAT image.  Nice composure.  I bet some thought and time went into this.  Hope you do well :))</td>', 'GREAT image.  Nice composure.  I bet some thought and time went into this.  Hope you do well :))', '2005-02-28 02:19:22.000000', NULL, 1),
(1197939, 150827, 6349, '<td valign="top">Wonderful!  Going in favorites.  10</td>', 'Wonderful!  Going in favorites.  10', '2005-02-28 02:19:31.000000', NULL, 1),
(1197940, 151077, 31213, '<td valign="top">Love the angle :)</td>', 'Love the angle :)', '2005-02-28 02:20:19.000000', NULL, 1),
(1197941, 150861, 6349, '<td valign="top">this is really interesting.  not sure what it is supposed to convey or how it goes with the title but you got me thinking and wondering which is good.</td>', 'this is really interesting.  not sure what it is supposed to convey or how it goes with the title but you got me thinking and wondering which is good.', '2005-02-28 02:20:24.000000', NULL, 1),
(1197942, 150783, 6349, '<td valign="top">Great photo.  I love this one.  Really interested to see how this does in the challenge.  10</td>', 'Great photo.  I love this one.  Really interested to see how this does in the challenge.  10', '2005-02-28 02:21:24.000000', NULL, 1),
(1197945, 149451, 6349, '<td valign="top">Beautiful photo.  Crisp black and white with great contrast.  9</td>', 'Beautiful photo.  Crisp black and white with great contrast.  9', '2005-02-28 02:22:01.000000', NULL, 1),
(1197946, 150350, 6349, '<td valign="top">this is fantastic.</td>', 'this is fantastic.', '2005-02-28 02:22:33.000000', NULL, 1),
(1197949, 151125, 31213, '<td valign="top">Take off your helmet!  Stay a while!</td>', 'Take off your helmet!  Stay a while!', '2005-02-28 02:22:53.000000', NULL, 1),
(1197951, 150114, 6349, '<td valign="top">gotta love that bridge :) what time were you there?  looks pretty deserted.  hope it wasn''t too cold and windy. 7</td>', 'gotta love that bridge :) what time were you there?  looks pretty deserted.  hope it wasn''t too cold and windy. 7', '2005-02-28 02:23:44.000000', NULL, 1),
(1197991, 150869, 32108, '<td valign="top">Thought I was the only one to do this to pass time:) - 8</td>', 'Thought I was the only one to do this to pass time:) - 8', '2005-02-28 02:54:33.000000', NULL, 1),
(1197992, 151088, 31213, '<td valign="top">Nice image.  Very artistic.  Not a huge fan of the enormous tattoo...but hey....wont ding ya for that ;)</td>', 'Nice image.  Very artistic.  Not a huge fan of the enormous tattoo...but hey....wont ding ya for that ;)', '2005-02-28 02:54:35.000000', NULL, 1),
(1197994, 149430, 31213, '<td valign="top">This should WILL make top ten.  Everyone on this site can relate to it.  Nice work.</td>', 'This should WILL make top ten.  Everyone on this site can relate to it.  Nice work.', '2005-02-28 02:55:16.000000', NULL, 1),
(1197997, 150582, 31213, '<td valign="top">hmmm.  I know you were going for moody....but it came out a little too dark for me...I would like to have seen the faces more.  Aside from a bit of slopping lighting...<br/> <br/>Nice composure and idea.</td>', 'hmmm.  I know you were going for moody....but it came out a little too dark for me...I would like to have seen the faces more.  Aside from a bit of slopping lighting... Nice composure and idea.', '2005-02-28 02:56:32.000000', NULL, 1),
(1198002, 151050, 31213, '<td valign="top">Very artistic!  This image will get overlooked because people dont respect good abstracts when they see them.  I can picture this image framed and hung in several places.  Nice work!</td>', 'Very artistic!  This image will get overlooked because people dont respect good abstracts when they see them.  I can picture this image framed and hung in several places.  Nice work!', '2005-02-28 02:57:50.000000', NULL, 1),
(1198007, 149983, 31213, '<td valign="top">Good idea but not well executed.  If you try to think a little more "outside the box" you could have done a lot with the same idea.  Unfortunately this has a quickly done snapshotty feel to me....as I''m sure it will with many other voters.  Wish you the best...</td>', 'Good idea but not well executed.  If you try to think a little more "outside the box" you could have done a lot with the same idea.  Unfortunately this has a quickly done snapshotty feel to me....as I''m sure it will with many other voters.  Wish you the best...', '2005-02-28 03:00:43.000000', NULL, 1),
(1198009, 150482, 31213, '<td valign="top">Wow, very cool.  Should be a high finisher. :)</td>', 'Wow, very cool.  Should be a high finisher. :)', '2005-02-28 03:01:58.000000', NULL, 1),
(1198013, 150270, 31213, '<td valign="top">Lips are an odd pale color.  They sort of rub me the wrong way.  Looks like you might be sleeping in a freezer :)  Love the lighting and serenity of the pic as a whole.<br/> <br/> <br/>BTW, nice eyebrows ;)</td>', 'Lips are an odd pale color.  They sort of rub me the wrong way.  Looks like you might be sleeping in a freezer :)  Love the lighting and serenity of the pic as a whole.  BTW, nice eyebrows ;)', '2005-02-28 03:03:41.000000', NULL, 1),
(1198019, 150515, 31213, '<td valign="top">Beautiful colors!</td>', 'Beautiful colors!', '2005-02-28 03:08:25.000000', NULL, 1),
(1198020, 150997, 30364, '<td valign="top">It''s a nice photo,  but a truly awful putting stroke.</td>', 'It''s a nice photo,  but a truly awful putting stroke.', '2005-02-28 03:08:58.000000', NULL, 1),
(1198021, 150523, 31213, '<td valign="top">Beautiful shot!  The lighting and composure is extraordinary!</td>', 'Beautiful shot!  The lighting and composure is extraordinary!', '2005-02-28 03:09:12.000000', NULL, 1),
(1198022, 150729, 31213, '<td valign="top">A slight miss with the focus.  Otherwise a GREAT capture! :)</td>', 'A slight miss with the focus.  Otherwise a GREAT capture! :)', '2005-02-28 03:09:57.000000', NULL, 1),
(1198025, 150511, 31213, '<td valign="top">Love the surreal feeling.  Nice work</td>', 'Love the surreal feeling.  Nice work', '2005-02-28 03:11:08.000000', NULL, 1),
(1198064, 149397, 29269, '<td valign="top">Eyes... unnaturally white. Probably as a result of whitening the background. They just seem so unreal, that it bothers me when I look at this image. Otherwise, very good DoF, details are sharp both on the ball and on the left hand way behind. But eyes, I have to score it down some.</td>', 'Eyes... unnaturally white. Probably as a result of whitening the background. They just seem so unreal, that it bothers me when I look at this image. Otherwise, very good DoF, details are sharp both on the ball and on the left hand way behind. But eyes, I have to score it down some.', '2005-02-28 03:41:19.000000', NULL, 1),
(1198078, 150295, 30857, '<td valign="top">Great picture, I don''t like the border though.</td>', 'Great picture, I don''t like the border though.', '2005-02-28 04:10:12.000000', NULL, 1),
(1198080, 151042, 30857, '<td valign="top">Just wonderful</td>', 'Just wonderful', '2005-02-28 04:10:29.000000', NULL, 1),
(1198089, 150695, 5237, '<td valign="top">thats a g8 shot!!!    good luck!!!   nice light! nice idea! just gr8!!!</td>', 'thats a g8 shot!!!    good luck!!!   nice light! nice idea! just gr8!!!', '2005-02-28 04:20:58.000000', NULL, 1),
(1198091, 150407, 3607, '<td valign="top">nice DOF and composition.</td>', 'nice DOF and composition.', '2005-02-28 04:25:39.000000', NULL, 1),
(1198092, 151088, 3607, '<td valign="top">nice lighting and perspective</td>', 'nice lighting and perspective', '2005-02-28 04:26:18.000000', NULL, 1),
(1198093, 150659, 3607, '<td valign="top">a little dark, but i like the monochromatic style.  good capture.</td>', 'a little dark, but i like the monochromatic style.  good capture.', '2005-02-28 04:26:49.000000', NULL, 1),
(1198095, 150329, 5237, '<td valign="top">love this pic! gr8 for the challenge!!!</td>', 'love this pic! gr8 for the challenge!!!', '2005-02-28 04:27:40.000000', NULL, 1),
(1198096, 150852, 3607, '<td valign="top">the rest of the photo is so dark so the boat stands out fantastically but i wonder if it''s too dark.  nice composition.</td>', 'the rest of the photo is so dark so the boat stands out fantastically but i wonder if it''s too dark.  nice composition.', '2005-02-28 04:27:47.000000', NULL, 1),
(1198098, 150765, 3607, '<td valign="top">good idea.  the focus seems a bit soft.</td>', 'good idea.  the focus seems a bit soft.', '2005-02-28 04:28:13.000000', NULL, 1),
(1198100, 150861, 3607, '<td valign="top">i can see why you wanted to shoot these, but the idea (box, person''s legs, chair) doesn''t quite work for me.</td>', 'i can see why you wanted to shoot these, but the idea (box, person''s legs, chair) doesn''t quite work for me.', '2005-02-28 04:29:32.000000', NULL, 1),
(1198101, 150827, 3607, '<td valign="top">good composition, nice shot!</td>', 'good composition, nice shot!', '2005-02-28 04:29:55.000000', NULL, 1),
(1198103, 150817, 3607, '<td valign="top">great photo, light, composition . . . but someone reading the hobbit outside in the rain by a statue of a mother nursing her child is quite a strange interpretation of ''passing time''</td>', 'great photo, light, composition . . . but someone reading the hobbit outside in the rain by a statue of a mother nursing her child is quite a strange interpretation of ''passing time''', '2005-02-28 04:31:43.000000', NULL, 1),
(1198106, 150508, 3607, '<td valign="top">the person seems a bit overexposed.  i like how he seems like he is up in the sky.</td>', 'the person seems a bit overexposed.  i like how he seems like he is up in the sky.', '2005-02-28 04:36:34.000000', NULL, 1),
(1198107, 150738, 3607, '<td valign="top">looks like the right moment won''t be for another couple of months (temp wise ;-)<br/> <br/>the photo seems to be a little too tight on her and the board, and doesn''t capture enough of the beach and ocean.  also seems a bit underexposed.</td>', 'looks like the right moment won''t be for another couple of months (temp wise ;-) the photo seems to be a little too tight on her and the board, and doesn''t capture enough of the beach and ocean.  also seems a bit underexposed.', '2005-02-28 04:38:52.000000', NULL, 1),
(1198108, 150997, 3607, '<td valign="top">given how blah the sky is, i wonder if you could have taken a shot where only green would be in the background.</td>', 'given how blah the sky is, i wonder if you could have taken a shot where only green would be in the background.', '2005-02-28 04:40:49.000000', NULL, 1),
(1198109, 150282, 3607, '<td valign="top">looks like you were having a good/bad weather day.  nice find.  might have been made more powerful if there had been someone sitting in the bench doing some reflection.</td>', 'looks like you were having a good/bad weather day.  nice find.  might have been made more powerful if there had been someone sitting in the bench doing some reflection.', '2005-02-28 04:41:41.000000', NULL, 1),
(1198110, 151072, 3607, '<td valign="top">neat and interesting landscape, which perhaps could have been strengthened with a person in the chair passing this quality time.</td>', 'neat and interesting landscape, which perhaps could have been strengthened with a person in the chair passing this quality time.', '2005-02-28 04:46:16.000000', NULL, 1),
(1198111, 151032, 3607, '<td valign="top">focus seems a little soft (but that might be intentional and it looks appropriate).  the power of the image might have been improved if the coupld hadn''t looked like they were lost wandering through the grave yard but maybe if they had been contemplating a particular tombstone or just the whole space.</td>', 'focus seems a little soft (but that might be intentional and it looks appropriate).  the power of the image might have been improved if the coupld hadn''t looked like they were lost wandering through the grave yard but maybe if they had been contemplating a particular tombstone or just the whole space.', '2005-02-28 04:48:22.000000', NULL, 1),
(1198112, 151108, 3607, '<td valign="top">perhaps cropped a little too close . . .</td>', 'perhaps cropped a little too close . . .', '2005-02-28 04:49:18.000000', NULL, 1),
(1198113, 150405, 3607, '<td valign="top">waiting for people is a big reason for which people pass time, but your title tries a little too hard and your photo doesn''t quite deliver - the other person distracts, the focus is soft, the composition is awkward, and the letters staying in red don''t really add any value.</td>', 'waiting for people is a big reason for which people pass time, but your title tries a little too hard and your photo doesn''t quite deliver - the other person distracts, the focus is soft, the composition is awkward, and the letters staying in red don''t really add any value.', '2005-02-28 04:52:29.000000', NULL, 1),
(1198115, 149915, 3607, '<td valign="top">interesting try - perhaps the title ''three spirits still waiting for the dentist'' would have been a better title . . .</td>', 'interesting try - perhaps the title ''three spirits still waiting for the dentist'' would have been a better title . . .', '2005-02-28 04:54:31.000000', NULL, 1),
(1198116, 150791, 3607, '<td valign="top">i''m not sure if you mean ''retiring for bed'' or ''being retired'', but either way the cropping perhaps is a bit tight and the focus on the dog a bit soft.  i like the idea of the person and dog looking at the pages at the same time.</td>', 'i''m not sure if you mean ''retiring for bed'' or ''being retired'', but either way the cropping perhaps is a bit tight and the focus on the dog a bit soft.  i like the idea of the person and dog looking at the pages at the same time.', '2005-02-28 04:56:06.000000', NULL, 1),
(1198118, 149816, 3607, '<td valign="top">it looks like its going to go in, but given the setup (in your foyer) i think there is too much to distract the eye from the main subject (man, green, golf ball, bored dog).  also, the man is out of focus.</td>', 'it looks like its going to go in, but given the setup (in your foyer) i think there is too much to distract the eye from the main subject (man, green, golf ball, bored dog).  also, the man is out of focus.', '2005-02-28 05:01:13.000000', NULL, 1),
(1198119, 150838, 3607, '<td valign="top">interesting light and lack fo saturation, nice composition if but a bit tight on the cropping.</td>', 'interesting light and lack fo saturation, nice composition if but a bit tight on the cropping.', '2005-02-28 05:02:14.000000', NULL, 1),
(1198121, 150295, 3607, '<td valign="top">very nice shot.  i like the action/movement that is very effectively captured.  the boy and bird are a bit grainy i assume because of their movement (as the ripples in the water look fine).  i don''t like the border at all and the title is perhaps a bit too long (but those won''t affect my scoring).</td>', 'very nice shot.  i like the action/movement that is very effectively captured.  the boy and bird are a bit grainy i assume because of their movement (as the ripples in the water look fine).  i don''t like the border at all and the title is perhaps a bit too long (but those won''t affect my scoring).', '2005-02-28 05:04:47.000000', NULL, 1),
(1198123, 151021, 3607, '<td valign="top">very fun shot.  perhaps a bit too tightly cropped on one person.  it has too much of a ''snapshot'' quality to it although i''m at a loss for suggestions as to what could have been done for improvement . . .</td>', 'very fun shot.  perhaps a bit too tightly cropped on one person.  it has too much of a ''snapshot'' quality to it although i''m at a loss for suggestions as to what could have been done for improvement . . .', '2005-02-28 05:06:26.000000', NULL, 1),
(1198124, 150307, 3607, '<td valign="top">i think the DOF works against you here with the snount being in focus but the eyes a little soft.  also, the cropping is a bit tight (maybe if he had his leash in his mouth the waiting theme would have been further implied).</td>', 'i think the DOF works against you here with the snount being in focus but the eyes a little soft.  also, the cropping is a bit tight (maybe if he had his leash in his mouth the waiting theme would have been further implied).', '2005-02-28 05:08:00.000000', NULL, 1),
(1198125, 150552, 3607, '<td valign="top">fun shot - nice light, composition, and great sharpness/focus!</td>', 'fun shot - nice light, composition, and great sharpness/focus!', '2005-02-28 05:08:45.000000', NULL, 1),
(1198126, 150896, 3607, '<td valign="top">this is a tough shot because the fog makes the photo look grainy/flat.  focus seems sharp and nice composition.</td>', 'this is a tough shot because the fog makes the photo look grainy/flat.  focus seems sharp and nice composition.', '2005-02-28 05:10:06.000000', NULL, 1),
(1198127, 149849, 3607, '<td valign="top">perhaps the child doing his homework would have better captured the never ending learning experience.</td>', 'perhaps the child doing his homework would have better captured the never ending learning experience.', '2005-02-28 05:12:21.000000', NULL, 1),
(1198128, 150858, 3607, '<td valign="top">the icy ropes create an interesting subject, but the composition isn''t quite as powerful as i think it could be - either tighter on the ropes or less cropped to get more of the boat.  also, did you consider b&amp;w?</td>', 'the icy ropes create an interesting subject, but the composition isn''t quite as powerful as i think it could be - either tighter on the ropes or less cropped to get more of the boat.  also, did you consider b&w?', '2005-02-28 05:14:42.000000', NULL, 1),
(1198129, 150074, 3607, '<td valign="top">especially with kids, i think the photo would have benefitted from seeing them front on.  also, the location (walking in the street?!?!) doesn''t add much to the image.</td>', 'especially with kids, i think the photo would have benefitted from seeing them front on.  also, the location (walking in the street?!?!) doesn''t add much to the image.', '2005-02-28 05:15:58.000000', NULL, 1),
(1198132, 150999, 3607, '<td valign="top">what! no ice, fog, or wind?  ;-)<br/> <br/>the water is very pretty but the shadows on the people reduces the effectiveness of the shot (although it still looks like a very pleasant passage of time)</td>', 'what! no ice, fog, or wind?  ;-) the water is very pretty but the shadows on the people reduces the effectiveness of the shot (although it still looks like a very pleasant passage of time)', '2005-02-28 05:17:49.000000', NULL, 1),
(1198133, 150261, 3607, '<td valign="top">with this sort of sky and urban landscape i think b&amp;w would have been more powerful.  the focus is a bit soft, but you are one of the few that show people actually waiting vs. a lot of random ideas.</td>', 'with this sort of sky and urban landscape i think b&w would have been more powerful.  the focus is a bit soft, but you are one of the few that show people actually waiting vs. a lot of random ideas.', '2005-02-28 05:19:30.000000', NULL, 1),
(1198134, 150604, 3607, '<td valign="top">very neat shot.  great focus, good composition.</td>', 'very neat shot.  great focus, good composition.', '2005-02-28 05:19:56.000000', NULL, 1),
(1198135, 149504, 3607, '<td valign="top">i think b&amp;w would have worked well here, and perhaps a perspective that would have made the watch the dominant object in the photo and not the hand.  good focus and lighting and use of empty space.</td>', 'i think b&w would have worked well here, and perhaps a perspective that would have made the watch the dominant object in the photo and not the hand.  good focus and lighting and use of empty space.', '2005-02-28 05:21:04.000000', NULL, 1),
(1198139, 150919, 3607, '<td valign="top">the person using their cell phone to take a picture - with that light and that seat - is priceless.  however, this photo suffers from the same challenges.</td>', 'the person using their cell phone to take a picture - with that light and that seat - is priceless.  however, this photo suffers from the same challenges.', '2005-02-28 05:22:56.000000', NULL, 1),
(1198140, 151007, 3607, '<td valign="top">nice silhouette and sun on the water (i practicallly need my sunglasses).  good composition.</td>', 'nice silhouette and sun on the water (i practicallly need my sunglasses).  good composition.', '2005-02-28 05:24:08.000000', NULL, 1),
(1198141, 151077, 3607, '<td valign="top">i really like this shot.  i don''t think it has much to do with passing time but the composition, light, colors, distortion etc. are great.  i wish more people submitted photos like this.  8 (oh, and i love cycling).</td>', 'i really like this shot.  i don''t think it has much to do with passing time but the composition, light, colors, distortion etc. are great.  i wish more people submitted photos like this.  8 (oh, and i love cycling).', '2005-02-28 05:25:33.000000', NULL, 1),
(1198142, 150297, 3607, '<td valign="top">nice shot.  great field!  i can''t wait to find out where this was shot so i can go hang out there (and be happy).  i might have turned up the saturation a little, perhaps not quite such a tight crop and tried to get some more DOF - but overall still one of the better efforts for this challenge.</td>', 'nice shot.  great field!  i can''t wait to find out where this was shot so i can go hang out there (and be happy).  i might have turned up the saturation a little, perhaps not quite such a tight crop and tried to get some more DOF - but overall still one of the better efforts for this challenge.', '2005-02-28 05:27:10.000000', NULL, 1),
(1198143, 150061, 3607, '<td valign="top">i like the effect of the light through the windows on the right side of the picture (and a train station is a great place to get ''time passing'' pictures) but it''s still too dark and the person in the center of the photos detracts rather than adds to the overall shot.</td>', 'i like the effect of the light through the windows on the right side of the picture (and a train station is a great place to get ''time passing'' pictures) but it''s still too dark and the person in the center of the photos detracts rather than adds to the overall shot.', '2005-02-28 05:28:31.000000', NULL, 1),
