(1198701, 149915, 33542, '<td valign="top">really cool effect, but I would have cropped the door out of the left and straightened the picture (or made it more crooked, but right now it just looks like a mistake)</td>', 'really cool effect, but I would have cropped the door out of the left and straightened the picture (or made it more crooked, but right now it just looks like a mistake)', '2005-02-28 12:30:39.000000', NULL, 1),
(1198703, 149843, 33542, '<td valign="top">kinda scary...  :)</td>', 'kinda scary...  :)', '2005-02-28 12:31:31.000000', NULL, 1),
(1198708, 150637, 16636, '<td valign="top">great spot, you have an eye for interesting photos. Although probably not the most exciting image to many I really like it - good luck</td>', 'great spot, you have an eye for interesting photos. Although probably not the most exciting image to many I really like it - good luck', '2005-02-28 12:34:54.000000', NULL, 1),
(1198716, 151041, 24212, '<td valign="top">To me, the lighting looks a little harsh and I think that I would prefer to see all of the pieces in sharp focus in this type of shot.</td>', 'To me, the lighting looks a little harsh and I think that I would prefer to see all of the pieces in sharp focus in this type of shot.', '2005-02-28 12:42:00.000000', NULL, 1),
(1198718, 151054, 24212, '<td valign="top">I think that I''d prefer to see the headstone a little straighter and sharper. Love the shallow DOF.</td>', 'I think that I''d prefer to see the headstone a little straighter and sharper. Love the shallow DOF.', '2005-02-28 12:43:37.000000', NULL, 1),
(1198719, 150960, 24212, '<td valign="top">I''m not sure, but I think that I''d prefer this shot with the back of the seat cropped off.</td>', 'I''m not sure, but I think that I''d prefer this shot with the back of the seat cropped off.', '2005-02-28 12:44:43.000000', NULL, 1),
(1198720, 150595, 24212, '<td valign="top">Love the sky.</td>', 'Love the sky.', '2005-02-28 12:46:09.000000', NULL, 1),
(1198721, 151037, 24212, '<td valign="top">Brilliantly sharp. I feel, however, that the left eye being cropped in half as it is is a bit off-putting.</td>', 'Brilliantly sharp. I feel, however, that the left eye being cropped in half as it is is a bit off-putting.', '2005-02-28 12:47:45.000000', NULL, 1),
(1198725, 150515, 24212, '<td valign="top">Wonderful colours and texture. It seems a pity that the angler''s head is a little lost against the land behind.</td>', 'Wonderful colours and texture. It seems a pity that the angler''s head is a little lost against the land behind.', '2005-02-28 12:49:10.000000', NULL, 1),
(1198727, 150929, 24212, '<td valign="top">I think that this might have a little more impact with some of the foreground cropped away.</td>', 'I think that this might have a little more impact with some of the foreground cropped away.', '2005-02-28 12:51:39.000000', NULL, 1),
(1198731, 150765, 24212, '<td valign="top">Very interesting, although I''d prefer to see it maybe a little sharper.</td>', 'Very interesting, although I''d prefer to see it maybe a little sharper.', '2005-02-28 12:52:27.000000', NULL, 1),
(1198737, 150943, 24212, '<td valign="top">It took a little studying to work out what this was. The dark, blurred material in the foreground confused me for a minute. The centre of attention is nicely sharp, though.</td>', 'It took a little studying to work out what this was. The dark, blurred material in the foreground confused me for a minute. The centre of attention is nicely sharp, though.', '2005-02-28 12:54:34.000000', NULL, 1),
(1198741, 150603, 24212, '<td valign="top">Interesting angle on the chesspieces, but it could do with being a bit sharper for more punch.</td>', 'Interesting angle on the chesspieces, but it could do with being a bit sharper for more punch.', '2005-02-28 12:55:36.000000', NULL, 1),
(1198746, 150329, 24212, '<td valign="top">I feel that the face, in particular, needs to be a touch brighter to really lift it away from the background.</td>', 'I feel that the face, in particular, needs to be a touch brighter to really lift it away from the background.', '2005-02-28 12:57:08.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1198750, 150781, 24212, '<td valign="top">Beautifully lit, but shouldn''t he be watching for a bite?</td>', 'Beautifully lit, but shouldn''t he be watching for a bite?', '2005-02-28 12:58:03.000000', NULL, 1),
(1198753, 150286, 24212, '<td valign="top">Interesting image.  I like the detail.</td>', 'Interesting image.  I like the detail.', '2005-02-28 12:58:51.000000', NULL, 1),
(1198758, 150601, 24212, '<td valign="top">I can see that the body is nicely in focus, but my eye keeps getting drawn to the top of the head, which appears to be softly focussed.</td>', 'I can see that the body is nicely in focus, but my eye keeps getting drawn to the top of the head, which appears to be softly focussed.', '2005-02-28 13:00:51.000000', NULL, 1),
(1198762, 150519, 24212, '<td valign="top">Nicely lit, but I get  no real feel of action.</td>', 'Nicely lit, but I get  no real feel of action.', '2005-02-28 13:01:27.000000', NULL, 1),
(1198766, 150869, 32837, '<td valign="top">Wow! You got some balls, or um you know what I mean. Very well done and sensual. It''s how I pass the time alomst every day!</td>', 'Wow! You got some balls, or um you know what I mean. Very well done and sensual. It''s how I pass the time alomst every day!', '2005-02-28 13:02:55.000000', NULL, 1),
(1198770, 150765, 32837, '<td valign="top">makes me want to take a nap too.</td>', 'makes me want to take a nap too.', '2005-02-28 13:04:26.000000', NULL, 1),
(1198774, 150695, 24212, '<td valign="top">A real look of longing captured here.</td>', 'A real look of longing captured here.', '2005-02-28 13:05:29.000000', NULL, 1),
(1198778, 150655, 24212, '<td valign="top">I find it a little difficult to see what this is exactly. Nice and bright, though.</td>', 'I find it a little difficult to see what this is exactly. Nice and bright, though.', '2005-02-28 13:06:16.000000', NULL, 1),
(1198781, 151056, 24212, '<td valign="top">I think that you''ve captured the reflection brilliantly.</td>', 'I think that you''ve captured the reflection brilliantly.', '2005-02-28 13:07:01.000000', NULL, 1),
(1198784, 150955, 24212, '<td valign="top">I feel that this requires a bit of sharpening to really bring this out.</td>', 'I feel that this requires a bit of sharpening to really bring this out.', '2005-02-28 13:07:43.000000', NULL, 1),
(1198788, 150679, 24212, '<td valign="top">So bright and colourful.</td>', 'So bright and colourful.', '2005-02-28 13:08:07.000000', NULL, 1),
(1198789, 150664, 32837, '<td valign="top">crispy sharp pawn.</td>', 'crispy sharp pawn.', '2005-02-28 13:09:04.000000', NULL, 1),
(1198793, 150582, 24212, '<td valign="top">I feel that this needs a little sharpening to really make it stand out.</td>', 'I feel that this needs a little sharpening to really make it stand out.', '2005-02-28 13:09:59.000000', NULL, 1),
(1198794, 151120, 34039, '<td valign="top">I think the idea is great, but it is kind of washed out looking.  I would have liked it much better if the dice were crisper against the background (despite the title).</td>', 'I think the idea is great, but it is kind of washed out looking.  I would have liked it much better if the dice were crisper against the background (despite the title).', '2005-02-28 13:10:15.000000', NULL, 1),
(1198796, 150934, 24212, '<td valign="top">Great detail, good composition.</td>', 'Great detail, good composition.', '2005-02-28 13:10:31.000000', NULL, 1),
(1198798, 149843, 24212, '<td valign="top">Very good.</td>', 'Very good.', '2005-02-28 13:10:56.000000', NULL, 1),
(1198801, 150174, 33687, '<td valign="top">Nice idea, but there''s a little much empty space in the frame. However, the big issue I had with this photo was the amount of noise.</td>', 'Nice idea, but there''s a little much empty space in the frame. However, the big issue I had with this photo was the amount of noise.', '2005-02-28 13:11:42.000000', NULL, 1),
(1198806, 150482, 24212, '<td valign="top">Very Escher. Just a touch more sharpening, perhaps?</td>', 'Very Escher. Just a touch more sharpening, perhaps?', '2005-02-28 13:14:31.000000', NULL, 1),
(1198809, 150656, 33687, '<td valign="top">This is not an easy image to pull off. Unfortunately this attempt has hot spots on the cat and fish. Looking at this photo though I get the feeling that the fish is more the subject than the cat, therefore I might have attempted the same shot with the fish being in focus.</td>', 'This is not an easy image to pull off. Unfortunately this attempt has hot spots on the cat and fish. Looking at this photo though I get the feeling that the fish is more the subject than the cat, therefore I might have attempted the same shot with the fish being in focus.', '2005-02-28 13:15:01.000000', NULL, 1),
(1198810, 150261, 24212, '<td valign="top">I find that this all looks a little too ''busy''.</td>', 'I find that this all looks a little too ''busy''.', '2005-02-28 13:15:25.000000', NULL, 1),
(1198815, 150908, 24212, '<td valign="top">I like it, but would prefer to see it a bit sharper.</td>', 'I like it, but would prefer to see it a bit sharper.', '2005-02-28 13:16:27.000000', NULL, 1),
(1198820, 151129, 33687, '<td valign="top">The vinetting either from the lens or flash is rather distractin. However, I''m not a fan of breaking the bubble.</td>', 'The vinetting either from the lens or flash is rather distractin. However, I''m not a fan of breaking the bubble.', '2005-02-28 13:17:42.000000', NULL, 1),
(1198826, 151043, 33687, '<td valign="top">Interesting concept. I''d like to have seen this having been in sharper focus though.</td>', 'Interesting concept. I''d like to have seen this having been in sharper focus though.', '2005-02-28 13:19:11.000000', NULL, 1),
(1198838, 150695, 33687, '<td valign="top">The shadow depth on the left side of the photo doesn''t seem to match the depth on the right side. The highlights on her face end up washing out much of the detail as well.</td>', 'The shadow depth on the left side of the photo doesn''t seem to match the depth on the right side. The highlights on her face end up washing out much of the detail as well.', '2005-02-28 13:21:36.000000', NULL, 1),
(1198852, 151117, 33687, '<td valign="top">Fun, but the photo look like a friend/family snapshot. The photo seems too busy so I''d look at tightening up the frame and going portrait vs. landscape.</td>', 'Fun, but the photo look like a friend/family snapshot. The photo seems too busy so I''d look at tightening up the frame and going portrait vs. landscape.', '2005-02-28 13:25:49.000000', NULL, 1),
(1198857, 150500, 33687, '<td valign="top">Warm and emotional. The backlight seems a bit harsh though and the change in background seems out of place.</td>', 'Warm and emotional. The backlight seems a bit harsh though and the change in background seems out of place.', '2005-02-28 13:27:25.000000', NULL, 1),
(1198861, 150657, 33687, '<td valign="top">I''d look at shifting the whole frame right to chop off some of the grinder and show more of the person,</td>', 'I''d look at shifting the whole frame right to chop off some of the grinder and show more of the person,', '2005-02-28 13:29:19.000000', NULL, 1),
(1198868, 150661, 33687, '<td valign="top">Humorous. The lighting could have been improved though to improve my rating.</td>', 'Humorous. The lighting could have been improved though to improve my rating.', '2005-02-28 13:31:01.000000', NULL, 1),
(1198875, 149843, 3102, '<td valign="top">Ha!  Very clever set-up, I must say!</td>', 'Ha!  Very clever set-up, I must say!', '2005-02-28 13:33:18.000000', NULL, 1),
(1198880, 150742, 33687, '<td valign="top">Interesting. I''m not sure what might improve this image, but its a little busy.</td>', 'Interesting. I''m not sure what might improve this image, but its a little busy.', '2005-02-28 13:34:01.000000', NULL, 1),
(1198885, 150919, 33687, '<td valign="top">Nice attempt. I might think about bloosting the sensor''s gain (ISO) to avoid using the flash.</td>', 'Nice attempt. I might think about bloosting the sensor''s gain (ISO) to avoid using the flash.', '2005-02-28 13:35:13.000000', NULL, 1),
(1198900, 150972, 33687, '<td valign="top">Dark with a hot spot around the banner. You have some different colors in your lighting detracting from the image.</td>', 'Dark with a hot spot around the banner. You have some different colors in your lighting detracting from the image.', '2005-02-28 13:37:14.000000', NULL, 1),
(1198908, 150604, 33687, '<td valign="top">Interesting shot. The color depth on the bike and rider is a little shallow though.</td>', 'Interesting shot. The color depth on the bike and rider is a little shallow though.', '2005-02-28 13:38:31.000000', NULL, 1),
(1198913, 150765, 7778, '<td valign="top">This is the finest image I could find in this challenge (I rated it ''7''). <br/>Its quiet retro charm (the ornate wrought iron pot holder, the potted palm so reminiscent of turn-of-the-century photographs, the chosen focal length etc.) is complimented by the -relative- modesty of the portrait, considering a contemporary context. Nevertheless, the understated sensuality of this capture is as riveting as is the manner of the photo, so sensitized to its inherently specific visual and emotional qualities.<br/> <br/>Despite the extreme wide format and minor compositional challenges which appear to have been accepted into the picture unmended or unaddressed (the redundant curvature of the deck, bottom right; the proximity of objects to the margins), the photo can, IMO, be easily viewed as a formal portrait alongside those found in the archives of photographic history and art.<br/> <br/>On a technical note, the exposure for highlights, here, is examplary.</td>', 'This is the finest image I could find in this challenge (I rated it ''7''). Its quiet retro charm (the ornate wrought iron pot holder, the potted palm so reminiscent of turn-of-the-century photographs, the chosen focal length etc.) is complimented by the -relative- modesty of the portrait, considering a contemporary context. Nevertheless, the understated sensuality of this capture is as riveting as is the manner of the photo, so sensitized to its inherently specific visual and emotional qualities. Despite the extreme wide format and minor compositional challenges which appear to have been accepted into the picture unmended or unaddressed (the redundant curvature of the deck, bottom right; the proximity of objects to the margins), the photo can, IMO, be easily viewed as a formal portrait alongside those found in the archives of photographic history and art. On a technical note, the exposure for highlights, here, is examplary.', '2005-02-28 13:40:18.000000', NULL, 1),
(1198915, 151009, 29269, '<td valign="top">Ooh, I''ve been wrong before when predicting blue ribbon winners, I realize that, but how can I go wrong here? 10, the only one so far.</td>', 'Ooh, I''ve been wrong before when predicting blue ribbon winners, I realize that, but how can I go wrong here? 10, the only one so far.', '2005-02-28 13:40:38.000000', NULL, 1),
(1198926, 150898, 33687, '<td valign="top">The depth-of-field on this shot looks odd. Perhaps having the whole controller in focus with the cable out of focus?</td>', 'The depth-of-field on this shot looks odd. Perhaps having the whole controller in focus with the cable out of focus?', '2005-02-28 13:42:13.000000', NULL, 1),
(1198931, 150766, 33379, '<td valign="top">thats very pretty!</td>', 'thats very pretty!', '2005-02-28 13:44:07.000000', NULL, 1),
(1198933, 151050, 33687, '<td valign="top">The photo comes across as blurry and low contrast. Increasing the contrast between the background and the subject might have been all that was needed to improve.</td>', 'The photo comes across as blurry and low contrast. Increasing the contrast between the background and the subject might have been all that was needed to improve.', '2005-02-28 13:44:27.000000', NULL, 1),
(1198935, 150604, 33652, '<td valign="top">Great capture.</td>', 'Great capture.', '2005-02-28 13:45:12.000000', NULL, 1),
(1198939, 150869, 33379, '<td valign="top">omg, my friend told me to take a photo like that lol, i said no way! but that is a good way to pass time lol</td>', 'omg, my friend told me to take a photo like that lol, i said no way! but that is a good way to pass time lol', '2005-02-28 13:46:21.000000', NULL, 1),
(1198947, 150869, 33687, '<td valign="top">The harsh lighting and noise on the back wall lost the points in my voting. The stark shadows created from the light source (especially from the pillow across the back wall) strike me as being unnatural but attempting to simulate natural window lighting.</td>', 'The harsh lighting and noise on the back wall lost the points in my voting. The stark shadows created from the light source (especially from the pillow across the back wall) strike me as being unnatural but attempting to simulate natural window lighting.', '2005-02-28 13:48:56.000000', NULL, 1),
(1198950, 150343, 33687, '<td valign="top">Nice landscape, but the noise in the trees and blown out highlights detract from hte image.</td>', 'Nice landscape, but the noise in the trees and blown out highlights detract from hte image.', '2005-02-28 13:50:27.000000', NULL, 1),
(1198959, 150929, 33687, '<td valign="top">Interesting reading material for poolside :) The background seems a little too busy to me. Perhaps narrowing the depth-of-field or re-framing to eliminate some of the accessories in the background could simplify the image.</td>', 'Interesting reading material for poolside :) The background seems a little too busy to me. Perhaps narrowing the depth-of-field or re-framing to eliminate some of the accessories in the background could simplify the image.', '2005-02-28 13:52:34.000000', NULL, 1),
(1198964, 150511, 33687, '<td valign="top">This has a 3D feel like the ViewMasters. This almost seems a little too tight though, like he should have move room infront of him.</td>', 'This has a 3D feel like the ViewMasters. This almost seems a little too tight though, like he should have move room infront of him.', '2005-02-28 13:54:28.000000', NULL, 1),
(1198973, 150863, 31865, '<td valign="top">that''s one huge apr. I wouldnt have advertised that so big if I was that credit card company.  Cool shot.  I like the colors.</td>', 'that''s one huge apr. I wouldnt have advertised that so big if I was that credit card company.  Cool shot.  I like the colors.', '2005-02-28 13:59:41.000000', NULL, 1),
