(1200412, 151111, 32774, '<td valign="top">very good. eye starts at the sunset follows the horizon to the plane trail, to the girl, down the beach line and right back up to the sunset.  Perfect planning, perfect picture.</td>', 'very good. eye starts at the sunset follows the horizon to the plane trail, to the girl, down the beach line and right back up to the sunset.  Perfect planning, perfect picture.', '2005-03-01 01:48:59.000000', NULL, 1),
(1200415, 150791, 18932, '<td valign="top">Sorry, too much highlights and too many distractions from what could have otherwise been an awesome shot. The mark next to the dog''s eye is the most distracting. 4</td>', 'Sorry, too much highlights and too many distractions from what could have otherwise been an awesome shot. The mark next to the dog''s eye is the most distracting. 4', '2005-03-01 01:50:34.000000', NULL, 1),
(1200418, 150552, 34039, '<td valign="top">Wow.  You must have hung some of those clocks by strings or something, either that or you have an amazing juggler on hand.  I love the composition and the contrast.  The effect is very surreal.</td>', 'Wow.  You must have hung some of those clocks by strings or something, either that or you have an amazing juggler on hand.  I love the composition and the contrast.  The effect is very surreal.', '2005-03-01 01:54:26.000000', NULL, 1),
