(1200445, 150211, 24212, '<td valign="top">I like the bleak look and I think that the composition is great. The path leading off into the distance really works well.</td>', 'I like the bleak look and I think that the composition is great. The path leading off into the distance really works well.', '2005-03-01 02:27:43.000000', NULL, 1),
(1200448, 151072, 24212, '<td valign="top">I like the idea, but feel that it might work a little better either with the camera rotated to the right a bit more or with the left side of the frame cropped, just so that the chair is almost at the edge of the frame. Great sharpness.</td>', 'I like the idea, but feel that it might work a little better either with the camera rotated to the right a bit more or with the left side of the frame cropped, just so that the chair is almost at the edge of the frame. Great sharpness.', '2005-03-01 02:30:38.000000', NULL, 1),
(1200450, 149567, 24212, '<td valign="top">There appear to be a couple of blobs at the top left of the frame which might have been removed. Other than that, great sharpness and texture.</td>', 'There appear to be a couple of blobs at the top left of the frame which might have been removed. Other than that, great sharpness and texture.', '2005-03-01 02:32:33.000000', NULL, 1),
(1200452, 150500, 24212, '<td valign="top">I don''t normally like blurred photos, even when it''s intentional. I''ll make an exception here. One thing I particularly like is the way that the change in background colour from black to white leads down through the hairline of the lady, creating a strong diagonal.</td>', 'I don''t normally like blurred photos, even when it''s intentional. I''ll make an exception here. One thing I particularly like is the way that the change in background colour from black to white leads down through the hairline of the lady, creating a strong diagonal.', '2005-03-01 02:36:15.000000', NULL, 1),
(1200454, 150927, 24212, '<td valign="top">I think that the flare from the candle overpowers the rest of the image.</td>', 'I think that the flare from the candle overpowers the rest of the image.', '2005-03-01 02:37:12.000000', NULL, 1),
