INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1200895, 151129, 24212, '<td valign="top">What a great expression of joy. Really like the angle. Fill flash works really well here.</td>', 'What a great expression of joy. Really like the angle. Fill flash works really well here.', '2005-03-01 11:26:44.000000', NULL, 1),
(1200903, 151009, 18095, '<td valign="top">Thank goodness he wasn''t thinking about tunaFabulous</td>', 'Thank goodness he wasn''t thinking about tunaFabulous', '2005-03-01 11:40:56.000000', NULL, 1),
(1200938, 150604, 24212, '<td valign="top">Great stopped-motion capture. The sky is great.</td>', 'Great stopped-motion capture. The sky is great.', '2005-03-01 12:27:50.000000', NULL, 1),
(1200942, 151069, 24212, '<td valign="top">A great sense of depth. Lovely, bright colours and a goodly amount of sharpness.</td>', 'A great sense of depth. Lovely, bright colours and a goodly amount of sharpness.', '2005-03-01 12:28:59.000000', NULL, 1),
(1200946, 151013, 24212, '<td valign="top">I wonder if the composition would work a little better if the top edge were to be cropped off, so that the image is a bit more symmetrical as far as the reflection goes.</td>', 'I wonder if the composition would work a little better if the top edge were to be cropped off, so that the image is a bit more symmetrical as far as the reflection goes.', '2005-03-01 12:32:43.000000', NULL, 1),
(1200949, 150766, 24212, '<td valign="top">What beautiful colours and sharpness. Great depth of field. I wonder whether you used a tool in post-processing to bring the sky under control, as there appear to be large haloes around the tops of the buildings and there seems to be a quite dark patch in the centre of the sky. Regardless of that, I think that this is a great picture.</td>', 'What beautiful colours and sharpness. Great depth of field. I wonder whether you used a tool in post-processing to bring the sky under control, as there appear to be large haloes around the tops of the buildings and there seems to be a quite dark patch in the centre of the sky. Regardless of that, I think that this is a great picture.', '2005-03-01 12:36:33.000000', NULL, 1),
(1200951, 150651, 24212, '<td valign="top">To me, the lighting is a bit harsh on the main subject.</td>', 'To me, the lighting is a bit harsh on the main subject.', '2005-03-01 12:37:39.000000', NULL, 1),
(1200956, 151021, 24212, '<td valign="top">That''s a very intent look.</td>', 'That''s a very intent look.', '2005-03-01 12:42:06.000000', NULL, 1),
(1200958, 150827, 24212, '<td valign="top">A nice candid. I wonder whether cropping out the chair on the left would make a difference, as I feel that it intrudes a bit.</td>', 'A nice candid. I wonder whether cropping out the chair on the left would make a difference, as I feel that it intrudes a bit.', '2005-03-01 12:43:45.000000', NULL, 1),
(1200959, 150507, 24212, '<td valign="top">This seems a bit too low-key for my tastes. I''d prefer to see the subjects a little more brightly lit.</td>', 'This seems a bit too low-key for my tastes. I''d prefer to see the subjects a little more brightly lit.', '2005-03-01 12:45:35.000000', NULL, 1),
(1200960, 150508, 24212, '<td valign="top">Great lighting. I like the composition.</td>', 'Great lighting. I like the composition.', '2005-03-01 12:46:13.000000', NULL, 1),
(1200963, 149452, 24212, '<td valign="top">I think that this could do without the third person in the background.</td>', 'I think that this could do without the third person in the background.', '2005-03-01 12:47:36.000000', NULL, 1),
(1200964, 150475, 24212, '<td valign="top">Wonderful. I love the big cats. Great bokeh - it really makes the shot.</td>', 'Wonderful. I love the big cats. Great bokeh - it really makes the shot.', '2005-03-01 12:48:26.000000', NULL, 1),
(1200965, 150796, 24212, '<td valign="top">I think that I''d prefer to see just a little more DOF here, so that the whole of the ''Go'' square is in focus.</td>', 'I think that I''d prefer to see just a little more DOF here, so that the whole of the ''Go'' square is in focus.', '2005-03-01 12:49:42.000000', NULL, 1),
(1200967, 150295, 24212, '<td valign="top">I like the capture. I do feel, however, that the duck in the background is a bit superfluous.</td>', 'I like the capture. I do feel, however, that the duck in the background is a bit superfluous.', '2005-03-01 12:50:58.000000', NULL, 1),
(1200970, 150858, 24212, '<td valign="top">I love the capture of the ice. I feel, however,  that a little more sharpening would not go amiss.</td>', 'I love the capture of the ice. I feel, however,  that a little more sharpening would not go amiss.', '2005-03-01 12:53:00.000000', NULL, 1),
(1200971, 150993, 24212, '<td valign="top">I really like the lighting with just a hint of shadows from the cube.</td>', 'I really like the lighting with just a hint of shadows from the cube.', '2005-03-01 12:53:55.000000', NULL, 1),
(1200975, 150637, 24212, '<td valign="top">The sunny, relaxed feel is great.</td>', 'The sunny, relaxed feel is great.', '2005-03-01 12:54:48.000000', NULL, 1),
(1200977, 150825, 24212, '<td valign="top">A good silhouette, although the water looks neither blurred enough nor sharp enough to me, if you get what I mean.</td>', 'A good silhouette, although the water looks neither blurred enough nor sharp enough to me, if you get what I mean.', '2005-03-01 12:56:34.000000', NULL, 1),
