(1206807, 150295, 5286, '<td valign="top">This would have been a ten but for the border. It really is a great capture and wonderfully composed, esp. hard with candids. Good job. Wish the border were absolutely not this, though..</td>', 'This would have been a ten but for the border. It really is a great capture and wonderfully composed, esp. hard with candids. Good job. Wish the border were absolutely not this, though..', '2005-03-03 23:17:51.000000', NULL, 1),
(1206833, 150827, 30364, '<td valign="top">What a brilliant composition!  It looks self-evident now that you''ve done it, but it would have been easy to get this all wrong, and you didn''t.  You got it exactly right, in my view.  8</td>', 'What a brilliant composition!  It looks self-evident now that you''ve done it, but it would have been easy to get this all wrong, and you didn''t.  You got it exactly right, in my view.  8', '2005-03-03 23:26:48.000000', NULL, 1),
