(1206846, 150533, 30364, '<td valign="top">This is powerful because it''s disturbing.  Many interpretations are possible, none of which seem comfortable.  7.</td>', 'This is powerful because it''s disturbing.  Many interpretations are possible, none of which seem comfortable.  7.', '2005-03-03 23:31:12.000000', NULL, 1),
(1206897, 150350, 30364, '<td valign="top">I think Melville might have loved this photograph (although he may have lamented the spelling of "scrivener").  The cropped anonymity, the blank wall, and the dead flowers he "preferred not to give water" are most apposite.  7</td>', 'I think Melville might have loved this photograph (although he may have lamented the spelling of "scrivener").  The cropped anonymity, the blank wall, and the dead flowers he "preferred not to give water" are most apposite.  7', '2005-03-03 23:53:28.000000', NULL, 1),
