(1212459, 149616, 34604, '<td valign="top">Congratulations! Please enter more photos. I love your work.</td>', 'Congratulations! Please enter more photos. I love your work.', '2005-03-07 11:36:44.000000', NULL, 0),
(1212538, 150343, 33284, '<td valign="top">Thank you all for your critiques.  It is hard to shoot into the sun.  The original was too bright in the sky and everyting else too dark.  Also, I did not want to disturb this guy and his truck was parked off to the left, which I did not want in the photo.  Would have prefered having sun at my back and better elements for the composition but this was better than nothing, I guess.  I learned from your comments.</td>', 'Thank you all for your critiques.  It is hard to shoot into the sun.  The original was too bright in the sky and everyting else too dark.  Also, I did not want to disturb this guy and his truck was parked off to the left, which I did not want in the photo.  Would have prefered having sun at my back and better elements for the composition but this was better than nothing, I guess.  I learned from your comments.', '2005-03-07 12:18:06.000000', NULL, 0),
(1212555, 150869, 19035, '<td valign="top">I was one of your ''10'' votes, based on creativity and boldness alone, I figured you''d get a lot of ones and my 10 might restore a bit of your deserved score.  Thanks for being provacative and thinking outise of the norm.</td>', 'I was one of your ''10'' votes, based on creativity and boldness alone, I figured you''d get a lot of ones and my 10 might restore a bit of your deserved score.  Thanks for being provacative and thinking outise of the norm.', '2005-03-07 12:23:09.000000', NULL, 0),
